update public.hikes set
  weather_policy = 'Water levels and footing can change quickly after heavy rain. We may postpone or redirect this hike when conditions around the waterfall or gorge are unsuitable.',
  what_to_bring = array['Waterproof or quick-drying layers','Grippy hiking footwear suitable for wet rock','Water and personal essentials','A small towel or change of clothes if getting close to the falls'],
  safety_info = 'This is a waterfall and gorge hike. Expect steep sections, streams and slippery rock, especially near the waterfall. Keep clear of unstable edges, take care on wet surfaces, and follow the guide route and instructions.',
  terrain = 'Steep descent/ascent on a partly shaded trail with streams, wet ground and slippery rock around the waterfall.',
  hike_type = 'Waterfalls hike',
  main_attraction = 'Cascade 500 Pieds waterfall and gorge'
where name = 'Cascade 500 Pieds';
